 const activeRecords=orders.filter(o=>!closedOrder(o)&&!unknownStatus(o)),activeOrders=activeRecords.filter(o=>!o.is_recharge),closedCount=orders.filter(closedOrder).length,statusPendingCount=orders.filter(unknownStatus).length,scope=S.overviewYear?activeOrders.filter(o=>o.date.startsWith(S.overviewYear)):activeOrders,st=J.stats(S.overviewYear?activeRecords.filter(o=>o.date.startsWith(S.overviewYear)):activeRecords);
