function itemEdit(id){const it=byId(id);if(!it)return;const p=J.priceFor(id),label=J.labelFor(id);openModal('核对这件商品',`<form id="item-form" class="dialog-body" data-id="${e(id)}"><p class="small">${e(it.name)}</p><p class="muted small">${e(it.order.date)} · 数量${it.qty} · ${itemPayment(id)}<br>实付是下单支付金额；净实付扣除已确认退款，用于低频投入统计。原始订单不改写。</p><label class="field">消费品类<select name="category">${opt('','自动识别：'+(it.category||'待确认'),!J.user.category_overrides[id]||J.user.category_overrides[id].archived?'':itemCategory(id))}${J.categories.filter(c=>c!=='充值储值'||it.order.is_recharge).map(c=>opt(c,c,J.user.category_overrides[id]&&!J.user.category_overrides[id].archived?itemCategory(id):'')).join('')}</select></label><p class="small muted">自动依据：${e(it.category_reason||'标题信息不足')}。本人分类只修正消费品类，预存现金流仍按原证据单列。${J.user.category_overrides[id]?`<br>本人记录：${e(J.user.category_overrides[id].category)} · ${J.user.category_overrides[id].archived?'已撤销':'使用中'} <button class="text-btn" type="button" data-act="category-history" data-id="${e(id)}">分类历史</button>`:''}</p><label class="field">分类备注（可选）<textarea name="category_note" rows="2" style="min-height:64px">${e(J.user.category_overrides[id]?.note||'')}</textarea></label><label class="field">低频筛选类型<select name="kind">${[['clothes','衣服'],['big','大件'],['other','不参与衣服 / 大件门槛筛选']].map(([v,t])=>opt(v,t,J.kindFor(id))).join('')}</select></label><label class="field">已核对的单件净实付（低频统计用；元，留空保持原状）<input name="unit_net" type="number" min="0" step="0.01" value="${p.verified?e(p.value):''}" placeholder="请根据实付及已确认退款填写"></label><label class="field">核对依据 / 备注<textarea name="note" rows="3" style="min-height:90px">${e(p.note||label?.note||'')}</textarea></label><p class="small muted">多件优惠、运费、退款无法分清时请留待核，不按件数自行均摊，也不用原价代替。</p><div class="actions"><button class="btn" type="submit">保存本人核对</button>${J.user.price_overrides?.[id]?`<button class="btn ghost" type="button" data-act="clear-price" data-id="${e(id)}">撤销价格修正</button>`:''}<button class="text-btn" type="button" data-act="price-history" data-id="${e(id)}">核对金额历史</button><button class="btn ghost" type="button" data-act="close-modal">取消</button></div></form>`);}
