const acts={backup:exportBackup,coverage:showCoverage,classification:showClassification,'category-history':b=>showCategoryHistory(b.dataset.id),'category-use':b=>{J.setCategory(b.dataset.id,b.dataset.cat);closeModal();render();},'close-modal':closeModal,nav:b=>go(b.dataset.module),year:b=>{S.archive={...S.archive,year:b.dataset.year,month:'',day:'',q:'',cat:'',page:1};go('archive');},category:b=>{closeModal();S.archive={...S.archive,year:S.overviewYear,month:'',day:'',q:'',cat:b.dataset.cat,page:1};go('archive');},'month-report':b=>{S.month=b.dataset.month;go('monthly');},'month-orders':b=>{S.archive={...S.archive,year:b.dataset.month.slice(0,4),month:b.dataset.month.slice(5),day:'',q:'',cat:'',page:1};go('archive');},day:b=>{S.archive.day=S.archive.day===b.dataset.day?'':b.dataset.day;S.archive.page=1;render();},'all-month':()=>{S.archive.day='';S.archive.page=1;render();},'arch-page':b=>{S.archive.page=+b.dataset.page;render();},'all-search':()=>{S.archive.year='';S.archive.month='';S.archive.day='';S.archive.q=$('#arch-q').value;S.archive.page=1;render();},'junk-tab':b=>{S.junk.tab=b.dataset.tab;S.junk.limit=30;render();},'more-junk':()=>{S.junk.limit+=30;render();},'label-low':b=>lowEdit(b.dataset.id),'label-ok':b=>{if(!closedOrder(byId(b.dataset.id)?.order)&&!unknownStatus(byId(b.dataset.id)?.order)){J.setLabel(b.dataset.id,'ok');render();}},'label-clear':b=>{J.setLabel(b.dataset.id,'clear');render();},'label-archive':b=>{J.archiveLabel(b.dataset.id,true);render();},'label-restore':b=>{J.archiveLabel(b.dataset.id,false);render();},'item-edit':b=>itemEdit(b.dataset.id),'clear-price':b=>{J.clearPrice(b.dataset.id);closeModal();render();},'note-edit':b=>noteEdit(b.dataset.month),'note-archive':b=>{J.archiveNote(b.dataset.month,true);render();},'note-restore':b=>{J.archiveNote(b.dataset.month,false);render();},'note-versions':b=>{const n=J.getNote(b.dataset.month);const vv=n?.versions||[];openModal('保留的回看版本',vv.length?vv.slice().reverse().map((v,i)=>`<div class="versions">${e(v.at||v.updated_at||'历史版本')}<br>${e(v.text||'')}<br><button class="text-btn" data-act="note-use-version" data-month="${b.dataset.month}" data-version="${vv.length-1-i}">恢复此版本</button></div>`).join(''):empty('尚无本人编辑的历史版本。'));},'note-use-version':b=>{const v=J.getNote(b.dataset.month)?.versions?.[+b.dataset.version];if(v){J.saveNote(b.dataset.month,v.text);closeModal();render();}},'todo-add':()=>todoEdit(''),'todo-edit':b=>todoEdit(b.dataset.id),'todo-archive':b=>{J.archiveTodo(b.dataset.id,true);render();},'todo-restore':b=>{J.archiveTodo(b.dataset.id,false);render();},image:b=>{const it=byId(b.dataset.id);if(imageFile(it))openModal(it.image_scope==='item'?'商品图片':'订单缩略图（未逐件核对）',`<img class="dialog-image" src="images/${encodeURIComponent(imageFile(it))}" alt="${e(it.name)}"><p class="small muted">${e(it.name)}</p>`);},orphans:()=>openModal('保留的旧标签',`<p class="small">无法安全对应的旧记录完整保留在导出备份中，不自动猜对应商品。</p>${Object.entries(J.user.orphan_labels||{}).map(([k,l])=>`<div class="versions">${e(k)} · ${e(l.status)}<br>${e(l.note||'无备注')}</div>`).join('')}`),'import-confirm':()=>{const r=J.commitImport(pendingImport);if(!r.ok){openModal('导入未完成',`<p>${e(r.errors.join('；'))}</p>`);return;}pendingImport=null;closeModal();render();if(!r.saved)openModal('已合并到本次页面，请导出',`<p>${e(r.errors.join('；'))}</p><button class="btn" data-act="backup">导出当前记录</button>`);},'import-backup':()=>download(pendingImport.backup,'消费手账_导入前备份.json')};
function priceHistory(id){const current=J.user.price_overrides[id];return [...(J.user.price_override_archives[id]||[]),...(current?.history||[]),...(current?[current]:[])].filter(row=>Number.isFinite(row.unit_net));}
acts['price-history']=b=>{const id=b.dataset.id,rows=priceHistory(id);openModal('保留的金额核对',rows.length?rows.map((row,i)=>`<div class="versions">单件净实付 ${money(row.unit_net)}<br>${e(row.updated_at||row.at||'')}<br>${e(row.note||'')}<button class="text-btn" data-act="price-restore" data-id="${e(id)}" data-version="${i}">恢复这个金额</button></div>`).join(''):empty('尚无本人金额核对历史。'));};
